from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    pieces = list(tiles[:n])
    if h <= 0 or w <= 0:
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in pieces]
    failed = set()

    shapes = []
    for a, b in pieces:
        orientations = {(a, b), (b, a)}
        shapes.append([(x, y) for x, y in orientations if x <= h and y <= w])

    def area_can_fill(remaining_area: int, available: int) -> bool:
        possible = {0}
        for i, area in enumerate(areas):
            if available & (1 << i):
                possible |= {value + area for value in tuple(possible)}
        return remaining_area in possible

    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        state = (occupied, used)
        if state in failed:
            return False

        remaining = h * w - occupied.bit_count()
        available = ((1 << len(pieces)) - 1) ^ used
        if not area_can_fill(remaining, available):
            failed.add(state)
            return False

        pos = next(i for i in range(h * w) if not (occupied >> i) & 1)
        row, col = divmod(pos, w)

        for i, piece_shapes in enumerate(shapes):
            bit = 1 << i
            if used & bit:
                continue
            for tile_h, tile_w in piece_shapes:
                if row + tile_h > h or col + tile_w > w:
                    continue
                mask = 0
                row_bits = (1 << tile_w) - 1
                for dy in range(tile_h):
                    mask |= row_bits << ((row + dy) * w + col)
                if occupied & mask:
                    continue
                if search(occupied | mask, used | bit):
                    return True

        failed.add(state)
        return False

    return search(0, 0)

