from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki play a card game; return the winner under optimal play.

    A turn consists of playing one card from the current player's hand onto the
    table, then optionally taking one card with a strictly smaller value from
    the table into that player's hand. A player with no card to play loses.
    """
    values = sorted(set(takahashi_cards + aoki_cards + table_cards))
    width = len(values)
    index = {value: i for i, value in enumerate(values)}

    initial_a = [0] * width
    initial_b = [0] * width
    initial_table = [0] * width
    for card in takahashi_cards:
        initial_a[index[card]] += 1
    for card in aoki_cards:
        initial_b[index[card]] += 1
    for card in table_cards:
        initial_table[index[card]] += 1

    @lru_cache(maxsize=None)
    def can_win(a: Tuple[int, ...], b: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        hand = a if turn == 0 else b
        if not any(hand):
            return False

        own = list(hand)
        board = list(table)
        for i, count in enumerate(hand):
            if not count:
                continue

            # Play this card. The option to take nothing is always available.
            own[i] -= 1
            board[i] += 1
            if turn == 0:
                next_a, next_b = tuple(own), b
            else:
                next_a, next_b = a, tuple(own)
            if not can_win(next_a, next_b, tuple(board), 1 - turn):
                return True

            # Alternatively take any strictly smaller card currently on table.
            for j in range(i):
                if not board[j]:
                    continue
                board[j] -= 1
                own[j] += 1
                if turn == 0:
                    next_a, next_b = tuple(own), b
                else:
                    next_a, next_b = a, tuple(own)
                if not can_win(next_a, next_b, tuple(board), 1 - turn):
                    return True
                own[j] -= 1
                board[j] += 1

            own[i] += 1
            board[i] -= 1

        return False

    return "Takahashi" if can_win(tuple(initial_a), tuple(initial_b), tuple(initial_table), 0) else "Aoki"

