def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has divisor sum divisible by 3."""
    import math
    from functools import lru_cache

    MOD = 998244353
    if N <= 100000:
        # Direct factorization branch also handles the small boundary cases.
        spf = list(range(N + 1))
        for p in range(2, math.isqrt(N) + 1):
            if spf[p] == p:
                for v in range(p * p, N + 1, p):
                    if spf[v] == v:
                        spf[v] = p
        comb = [1] * (N.bit_length() + 1)
        for e in range(1, len(comb)):
            comb[e] = comb[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD
        ans = 0
        for n in range(1, N + 1):
            x = n
            weight = 1
            sigma = 1
            while x > 1:
                p = spf[x]
                e = 0
                term = 1
                power = 1
                while x % p == 0:
                    x //= p
                    e += 1
                    power *= p
                    term += power
                weight = weight * comb[e] % MOD
                sigma = sigma * (term % 3) % 3
            if sigma == 0:
                ans += weight
        return ans % MOD

    INV2 = (MOD + 1) // 2
    limit = math.isqrt(N)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:min(2, limit + 1)] = b"\x00" * min(2, limit + 1)
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    vals = []
    l = 1
    while l <= N:
        v = N // l
        vals.append(v)
        l = N // v + 1
    pos = {v: i for i, v in enumerate(vals)}
    pi = [v - 1 for v in vals]
    ch = []
    for v in vals:
        _, r = divmod(v, 3)
        ch.append((1 if r >= 1 else 0) - (1 if r >= 2 else 0) - 1)
    prev_ch = 0
    for i, p in enumerate(primes):
        if p * p > N:
            break
        cp = 1 if p % 3 == 1 else (-1 if p % 3 == 2 else 0)
        for j, v in enumerate(vals):
            if v < p * p:
                break
            k = pos[v // p]
            pi[j] -= pi[k] - i
            ch[j] -= cp * (ch[k] - prev_ch)
        prev_ch += cp

    def prime_sum(x):
        if x < 2:
            return 0, 0
        return pi[pos[x]], ch[pos[x]]

    def nonzero_sigma_prime_sum(x):
        a, b = prime_sum(x)
        return (M * (a + b) * INV2 + (M * INV2 if x >= 3 else 0)) % MOD

    prefix = [0]
    for p in primes:
        prefix.append((prefix[-1] + (M if p % 3 == 1 or p == 3 else 0)) % MOD)
    comb = [1] * (N.bit_length() + 1)
    for e in range(1, len(comb)):
        comb[e] = comb[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    def allowed_weight(p, e):
        if p % 3 == 1 and e % 3 == 2:
            return 0
        if p % 3 == 2 and e % 2 == 1:
            return 0
        return comb[e]

    @lru_cache(None)
    def bad_sum(x, first):
        total = 1
        root = math.isqrt(x)
        i = first
        while i < len(primes) and primes[i] <= root:
            p = primes[i]
            power = p
            e = 1
            while power <= x:
                w = allowed_weight(p, e)
                if w:
                    total = (total + w * bad_sum(x // power, i + 1)) % MOD
                power *= p
                e += 1
            i += 1
        lo = first
        while lo < len(primes) and primes[lo] <= root:
            lo += 1
        return (total + nonzero_sigma_prime_sum(x) - prefix[lo]) % MOD

    @lru_cache(None)
    def all_sum(x, first):
        total = 1
        root = math.isqrt(x)
        i = first
        while i < len(primes) and primes[i] <= root:
            p = primes[i]
            power = p
            e = 1
            while power <= x:
                total = (total + comb[e] * all_sum(x // power, i + 1)) % MOD
                power *= p
                e += 1
            i += 1
        lo = first
        while lo < len(primes) and primes[lo] <= root:
            lo += 1
        prime_count, _ = prime_sum(x)
        return (total + M * (prime_count - lo)) % MOD

    return (all_sum(N, 0) - bad_sum(N, 0)) % MOD

