def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in [num1, num2] whose digit sums are in [min_sum, max_sum].

    The result is returned modulo 10^9 + 7.
    """
    mod = 1_000_000_007

    def decrement(value: str) -> str:
        digits = list(value)
        i = len(digits) - 1
        while digits[i] == "0":
            digits[i] = "9"
            i -= 1
        digits[i] = str(int(digits[i]) - 1)
        result = "".join(digits).lstrip("0")
        return result or "0"

    def count_at_most(bound: str) -> int:
        bound = bound.lstrip("0") or "0"
        limit = min(max_sum, 9 * len(bound))
        if min_sum > limit:
            return 0

        # less[s] counts prefixes already below the bound with digit sum s.
        less = [0] * (limit + 1)
        equal = [0] * (limit + 1)
        equal[0] = 1

        for char in bound:
            bound_digit = int(char)
            next_less = [0] * (limit + 1)
            next_equal = [0] * (limit + 1)

            for total, ways in enumerate(less):
                if ways:
                    upto = min(9, limit - total)
                    for digit in range(upto + 1):
                        next_less[total + digit] = (
                            next_less[total + digit] + ways
                        ) % mod

            for total, ways in enumerate(equal):
                if not ways:
                    continue
                upto = min(bound_digit - 1, limit - total)
                for digit in range(upto + 1):
                    next_less[total + digit] = (
                        next_less[total + digit] + ways
                    ) % mod
                if total + bound_digit <= limit:
                    next_equal[total + bound_digit] = ways

            less, equal = next_less, next_equal

        return (sum(less[min_sum:limit + 1]) +
                sum(equal[min_sum:limit + 1])) % mod

    return (count_at_most(num2) - count_at_most(decrement(num1))) % mod

