from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by
    their digit sum.
    """
    def upto(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        total = 0
        for target in range(1, 9 * len(digits) + 1):
            @lru_cache(None)
            def dp(pos: int, digit_sum: int, rem: int, started: bool, tight: bool) -> int:
                if digit_sum > target:
                    return 0
                if pos == len(digits):
                    return int(started and digit_sum == target and rem == 0)
                limit = digits[pos] if tight else 9
                result = 0
                for d in range(limit + 1):
                    ntight = tight and d == limit
                    if not started and d == 0:
                        result += dp(pos + 1, digit_sum, rem, False, ntight)
                    else:
                        new_sum = digit_sum + d
                        if new_sum <= target:
                            result += dp(pos + 1, new_sum, (rem * d) % target, True, ntight)
                return result

            total += dp(0, 0, 1 % target, False, True)
        return total

    return upto(r) - upto(l - 1)

