def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count integers in [start, finish] ending in s with every digit at most limit."""
    if start > finish or finish < 1 or limit < 0 or not s:
        return 0
    if any(int(ch) > limit for ch in s):
        return 0

    suffix_len = len(s)

    def count_prefixes_at_most(bound: int, length: int) -> int:
        if length == 0:
            return int(bound >= 0)
        if bound < 10 ** (length - 1):
            return 0
        digits = str(bound)
        if len(digits) > length:
            digits = digits[:length]
        elif len(digits) < length:
            digits = digits.zfill(length)
        total = 0
        for i, ch in enumerate(digits):
            digit = int(ch)
            low = 1 if i == 0 else 0
            choices = max(0, min(limit, digit - 1) - low + 1)
            remaining = length - i - 1
            total += choices * (limit + 1) ** remaining
            if digit < low or digit > limit:
                return total
        return total + 1

    def count_upto(n: int) -> int:
        if n < 1:
            return 0
        bound_text = str(n)
        max_len = len(bound_text)
        result = 0
        for total_len in range(suffix_len, max_len + 1):
            prefix_len = total_len - suffix_len
            if total_len < max_len:
                prefix_bound = 10 ** prefix_len - 1
            elif prefix_len == 0:
                if int(s) <= n:
                    result += 1
                continue
            else:
                prefix_text = bound_text[:prefix_len]
                suffix_text = bound_text[prefix_len:]
                prefix_bound = int(prefix_text)
                if s > suffix_text:
                    prefix_bound -= 1
            result += count_prefixes_at_most(prefix_bound, prefix_len)
        return result

    return count_upto(finish) - count_upto(start - 1)

