def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    """Return the minimum edits to partition s into k semi-palindromes."""
    n = len(s)
    # cost[i][j] is the minimum edit count for the half-open substring
    # s[i:j]. A valid spacing d must be a proper divisor of its length.
    cost = [[0] * (n + 1) for _ in range(n)]
    for i in range(n):
        for j in range(i + 2, n + 1):
            length = j - i
            best = length
            for d in range(1, length):
                if length % d:
                    continue
                edits = 0
                for residue in range(d):
                    count = (length - 1 - residue) // d + 1
                    for q in range(count // 2):
                        left = i + residue + q * d
                        right = i + residue + (count - 1 - q) * d
                        if s[left] != s[right]:
                            edits += 1
                if edits < best:
                    best = edits
            cost[i][j] = best

    inf = n + 1
    dp = [[inf] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for parts in range(1, k + 1):
        # Each segment has length at least two.
        for end in range(2 * parts, n + 1):
            for start in range(2 * (parts - 1), end - 1):
                if dp[parts - 1][start] < inf:
                    dp[parts][end] = min(
                        dp[parts][end],
                        dp[parts - 1][start] + cost[start][end],
                    )
    return dp[k][n]

