from functools import lru_cache
from math import comb, factorial
MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    if comb(N, M) < K ** M - 1:
        return 0
    valid_x = len(X) == M and all(1 <= v <= K for v in X)
    x = tuple(v - 1 for v in X) if valid_x else ()
    if N == M * K - 1:
        if valid_x and len(set(x)) == 1:
            return pow(factorial(K - 1), M, MOD)
        return 0

    if M == 3 and valid_x and len(set(x)) == 3 and K >= 3:
        a, b, c = x
        alphabet = [z for z in range(K) if z != c]
        bit_for = {z: 1 << i for i, z in enumerate(alphabet)}
        full_seen = (1 << len(alphabet)) - 1
        suffix_counts = [0] * N
        # The prefix already contains a; wait for the first subsequent b.
        pre0, pre1 = 0, 1
        post = [0] * (1 << len(alphabet))
        for length in range(1, N):
            next_pre0 = pre0 * (K - 2) % MOD
            next_pre1 = (pre0 + pre1 * (K - 2)) % MOD
            next_post = [0] * len(post)
            next_post[0] = pre1
            for mask, ways in enumerate(post):
                if ways:
                    for z in alphabet:
                        new_mask = mask | bit_for[z]
                        next_post[new_mask] = (next_post[new_mask] + ways) % MOD
            pre0, pre1, post = next_pre0, next_pre1, next_post
            suffix_counts[length] = post[full_seen]

        m = K - 1

        @lru_cache(None)
        def surjective_words(length):
            if length < m:
                return 0
            return sum(
                (-1 if j & 1 else 1) * comb(m, j) * pow(m - j, length, MOD)
                for j in range(m + 1)
            ) % MOD

        prefix_counts = [0] * N
        pair_conv = [0] * N
        for length in range(N):
            pair_conv[length] = sum(
                surjective_words(p) * surjective_words(length - p)
                for p in range(length + 1)
            ) % MOD
        for length in range(2, N):
            prefix_counts[length] = sum(
                pair_conv[length - 2 - q] * pow(K - 2, q, MOD)
                for q in range(length - 1)
            ) % MOD
        answer = 0
        for t in range(1, N):
            answer = (answer + prefix_counts[t - 1] * suffix_counts[N - t]) % MOD
        return answer

    if M == 2 and K == 2:
        if not valid_x:
            return 0
        return max(0, N - 2) if x[0] == x[1] else 0

    total_patterns = K ** M
    if valid_x:
        code = 0
        for value in x:
            code = code * K + value
        wanted = ((1 << total_patterns) - 1) ^ (1 << code)
    else:
        wanted = (1 << total_patterns) - 1

    @lru_cache(None)
    def suffix_avoidance(q, length):
        if not valid_x:
            return pow(K, length, MOD)
        ways = [0] * (M + 1)
        ways[q] = 1
        for _ in range(length):
            nxt = [0] * (M + 1)
            for matched in range(M):
                for ch in range(K):
                    q2 = matched + (ch == x[matched])
                    nxt[q2] = (nxt[q2] + ways[matched]) % MOD
            ways = nxt
        return sum(ways[:M]) % MOD

    prefix_codes = []
    if valid_x:
        for q in range(1, M + 1):
            code = 0
            for value in x[:q]:
                code = code * K + value
            prefix_codes.append((q, code))

    def matched_prefix(state):
        for q, code in reversed(prefix_codes):
            if state[q] >> code & 1:
                return q
        return 0

    dp = {(0,) * (M + 1): 1}
    answer = 0
    for depth in range(1, N + 1):
        nxt = {}
        for state, ways in dp.items():
            for ch in range(K):
                masks = list(state)
                masks[1] |= 1 << ch
                for length in range(2, M + 1):
                    old = state[length - 1]
                    while old:
                        bit = old & -old
                        old -= bit
                        code = (bit.bit_length() - 1) * K + ch
                        masks[length] |= 1 << code
                key = tuple(masks)
                nxt[key] = (nxt.get(key, 0) + ways) % MOD
        dp = {}
        remaining = N - depth
        for state, ways in nxt.items():
            if state[M] == wanted:
                answer = (answer + ways * suffix_avoidance(matched_prefix(state), remaining)) % MOD
            else:
                dp[state] = ways
        if not dp:
            break
    return answer

